package com.library.model;
import com.library.enums.TransactionStatus;
import java.math.BigDecimal; import java.time.LocalDate;
public class Transaction { private long transactionId,bookId,memberId; private String bookName,memberName; private LocalDate issueDate,dueDate,returnDate; private BigDecimal fine=BigDecimal.ZERO; private TransactionStatus status; public long getTransactionId(){return transactionId;} public void setTransactionId(long v){transactionId=v;} public long getBookId(){return bookId;} public void setBookId(long v){bookId=v;} public long getMemberId(){return memberId;} public void setMemberId(long v){memberId=v;} public String getBookName(){return bookName;} public void setBookName(String v){bookName=v;} public String getMemberName(){return memberName;} public void setMemberName(String v){memberName=v;} public LocalDate getIssueDate(){return issueDate;} public void setIssueDate(LocalDate v){issueDate=v;} public LocalDate getDueDate(){return dueDate;} public void setDueDate(LocalDate v){dueDate=v;} public LocalDate getReturnDate(){return returnDate;} public void setReturnDate(LocalDate v){returnDate=v;} public BigDecimal getFine(){return fine;} public void setFine(BigDecimal v){fine=v;} public TransactionStatus getStatus(){return status;} public void setStatus(TransactionStatus v){status=v;} }
